#!/usr/bin/env python3
"""读取 CSV 文件并统计每一列的非空值数量。"""
import argparse
import csv


def count_nonempty(path):
    counts = {}
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f)
        header = next(reader, [])
        for i, name in enumerate(header):
            counts[name] = 0
        extra_cols = {}
        for row in reader:
            for i, value in enumerate(row):
                if i < len(header):
                    key = header[i]
                else:
                    key = f"<第{i + 1}列(无表头)>"
                if value.strip():
                    if i < len(header):
                        counts[key] += 1
                    else:
                        extra_cols[key] = extra_cols.get(key, 0) + 1
        counts.update(extra_cols)
    return counts


def main():
    parser = argparse.ArgumentParser(description="统计 CSV 每一列的非空值数量")
    parser.add_argument("csv_file", help="CSV 文件路径")
    args = parser.parse_args()

    for name, count in count_nonempty(args.csv_file).items():
        print(f"{name}: {count}")


if __name__ == "__main__":
    main()
